const ultima_mensagem_da_fila = $input.last();
// AQUI ESTAVA O ERRO: Mudamos de 'Info3' para 'Info'
const mensagem_do_workflow = $('Info').first(); 

if (ultima_mensagem_da_fila.json.id_mensagem !== mensagem_do_workflow.json.id_mensagem) {
  // Se os IDs forem diferentes, é mensagem encavalada (duplicada/antiga), então paramos aqui.
  return [];
}

// Se for a mensagem certa, deixa passar.
return $input.all();

// Pega o texto do input de forma segura
const item = $input.first();
const texto = item && item.json.text ? item.json.text : "";

// Se não tiver texto, encerra rápido
if (!texto) return [];

// LÓGICA CORRIGIDA (ANTI-SPAM):
// Só divide se houver quebra de linha DUPLA (parágrafos distintos)
// Ignora pontos finais simples para evitar "metralhadora" de mensagens
const partes = texto.split(/\n\n+/);

const fragmentos = [];

for (let i = 0; i < partes.length; i++) {
    let bloco = partes[i].trim();

    // Só adiciona se tiver conteúdo
    if (bloco.length > 0) {
        fragmentos.push({
            json: {
                fragmento: bloco,
                caracteres: bloco.length
            }
        });
    }
}

return fragmentos;
